// th15_s1_w06 TH15 Stage 1：中 Boss 后 GirlC01 奖励编队（17 只）
// 源：st01.ecl.txt MainSub04 1016-1045（入口）、GirlC01 415-438、GirlC01_at 440-495。
// 已删除：章节入口/-9905 刷怪门控与 enmCreateF 的 F 门（本卡无 Boss）、普通掉落与纯表现。
// 卡帧 0 为空壳开场；卡帧 OPENING_BUFFER 起对应源 MainSub04 入口帧 0。

const TH15_RICE: int = 480;   // touhou-bullets.ecl：源 etSprite(0, 8, 6) 的 type 8
const TIME_LIMIT: int = 2524; // 120 缓冲 + 2400 排程/退场/尾弹估计 + 4
const OPENING_BUFFER: int = 120;

// 源 GirlC01_at 440-495。发射器配置在 wait(60) 之后，所有难度共用；
// 数量/循环次数/速度/等待按源难度掩码 (447-455, 460, 463-464, 470-479, 482-490) 取实际值。
async sub girl_c01_at() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var ways: int = 1;       // 源 etCount 压栈值：E1 N1 H2 L5
    var rounds: int = 1;     // 源 diffI($B, 1, 3, 6, 12)
    var base_speed: fx = 1fx; // 源 diffF(%A, 1.0, 1.5, 2.0, 3.0)
    var volleys: int = 6;    // 源 diffI($C, 6, 12, 12, 12)
    var gap: int = 4;        // 源内层 wait：E4 N4 H2 L1
    var rest: int = 60;      // 源内层结束后 wait：E60 N60 H30 L20
    if rank == RANK_NORMAL {
        ways = 1; rounds = 3; base_speed = 1.5fx; volleys = 12; gap = 4; rest = 60;
    }
    if rank == RANK_HARD {
        ways = 2; rounds = 6; base_speed = 2fx; volleys = 12; gap = 2; rest = 30;
    }
    if rank == RANK_LUNATIC {
        ways = 5; rounds = 12; base_speed = 3fx; volleys = 12; gap = 1; rest = 20;
    }

    sh_reset(0);                    // 源 444 etNew(0)
    sh_ring(0, 0);                  // 源 445 etAim(0, 1)：固定方向扇形
    sh_aim(0, 0);                   // 不瞄自机
    sh_sprite(0, TH15_RICE, 6);     // 源 446 etSprite(0, 8, 6)
    sh_count(0, ways, 1);           // 源 456 etCount(0, [-1], 1)
    sh_angle(0, 16384bam, 1274bam); // 源 457 etAngle(0, pi/2, 0.12217305=7deg)
    sh_speed(0, 1.6fx, 0fx);        // 源 458 etSpeed(0, 1.6, 1.0)；每波前被下面的 A 覆盖

    var r: int = 0;
    while r < rounds {
        var speed: fx = base_speed;
        var k: int = 0;
        while k < volleys {
            sh_speed(0, speed, 0fx);          // 源 467 etSpeed(0, %A, 0.0f)
            // 源 459 etEx(0, 0, 2, 1, ...)：type 2 ANIM，a=1 在出生时 position -= 4*velocity。
            // 目标用逐颗沿自身角度的出生距离表达这个退位移；前入参为负即反方向。
            sh_dist(0, 0fx - 4fx * speed);
            sh_fire(0);
            speed = speed + 0.15fx;           // 源 468 %A += 0.15f
            wait(gap);                        // 源 479 wait([-1])
            k = k + 1;
        }
        wait(rest);                           // 源 491 wait([-1])
        r = r + 1;
    }
}

// 源 GirlC01 415-438：判定、镜像移动与存活循环。
async sub girl_c01() {
    set_invuln(65535);   // 训练外壳：无敌不关体碰
    set_hurtbox(16fx);   // 源 423 setHurtbox(32,32) 普通圆取 0.5
    set_hitbox(12fx);    // 源 424 setHitbox(24,24) 普通圆取 0.5
    // 源 425-427：%FINAL_X > 0 时 moveSetMirror(1)。镜像只翻 x，用镜像角表达。
    var a0: angle = 8192bam;    // 源 428 moveVel(0.7853982f=45deg, 3)
    var a1: angle = 4096bam;    // 源 429 moveVelTime(80, mode1, 0.3926991f=22.5deg, 1)
    if $self_x > 0fx {
        a0 = 24576bam;          // 45deg 镜像
        a1 = 28672bam;          // 22.5deg 镜像
    }
    move_vel(0, a0, 3fx, EASE_LINEAR);
    move_vel(80, a1, 1fx, EASE_QUAD_IN);  // 源 mode1 = 二次加速，角速同曲线
    spawn girl_c01_at();                  // 源 430 async
    wait(60);                             // 源 431
    loop { wait(1000); }                  // 源 432-436：敌保持存活直到退场
}

// 源 MainSub04 1016-1045：4 轮四方向 + 最后一只，共 17 只；出生间隔 80。
sub spawn_girl(base: fx) {
    // 源 1023 等：_f(base) + (%RANDF2 * _f(16))，RANDF2 为 [-1,1]；每次创建抽一次。
    var u: int = rand(65536);
    var jitter: fx = ((u - 32768) as fx / 32768) * 16fx;
    _ = spawn_enemy(base + jitter, -24fx, 600, 0, 0, 0, girl_c01);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    for round in 0..4 {      // 源 1019 $A=4 的四个循环
        spawn_girl(-192fx);  // 源 1023
        wait(80);
        spawn_girl(192fx);   // 源 1027
        wait(80);
        spawn_girl(-256fx);  // 源 1031
        wait(80);
        spawn_girl(256fx);   // 源 1035
        wait(80);
    }
    spawn_girl(-192fx);      // 源 1041
    wait(19);                // 源 1043
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
